import{nativeProfile}from'./native-profile.mjs';import{verifyDesktopPayload}from'../bootstrap/desktop-payload.mjs';
import{readFile,writeFile,mkdir,lstat,stat,readdir,realpath,chmod}from'node:fs/promises';import{join,resolve,dirname,relative,isAbsolute}from'node:path';import{createHash}from'node:crypto';
const sha=b=>createHash('sha256').update(b).digest('hex'),fail=c=>{throw Error(c)},inside=(a,b)=>{const r=relative(a,b);return !isAbsolute(r)&&r!=='..'&&!r.startsWith('../')&&!r.startsWith('..\\')};
const sepOwners=new Set(['dsh-system-enhancement-package','@deepseek-ai/dsh-recovery','@deepseek-ai/dsh-client-ui-settings-memory','@deepseek-ai/dsh-desktop','@deepseek-ai/dsh-desktop-host','dsh-sep-plugin-group','dsh-sep-context-preparation','dsh-tool-worker','dsh-sep-trusted-evaluation-entry','@deepseek-ai/dsh-sep-session-migration','dsh-sep-brand']);
export async function buildNativeBundle({program,runtime,packaging,template,destination,kind,desktopPayload}){
 if(!['full','sep'].includes(kind)||![program,runtime,packaging,template,destination].every(isAbsolute))fail('BUNDLE_INPUT');destination=resolve(destination);try{await lstat(destination);fail('BUNDLE_DESTINATION_EXISTS')}catch(e){if(e.code!=='ENOENT')throw e}if(await realpath(dirname(destination))!==dirname(destination))fail('BUNDLE_DESTINATION_ALIAS');
 for(const input of [program,runtime,packaging])if(inside(await realpath(input),destination)||inside(destination,await realpath(input)))fail('BUNDLE_OVERLAP');
 const inputGraphBytes=await readFile(join(program,'graph.json')),graph=JSON.parse(inputGraphBytes);if(graph.kind!=='dsh-sep-local-offline-graph'||graph.platform!==process.platform+'-'+process.arch)fail('BUNDLE_PLATFORM'); const byName=new Map();for(const p of graph.packages){if(!p.name.startsWith('@deepseek-ai/')&&!p.name.startsWith('dsh-'))continue;const rows=byName.get(p.name)??[];rows.push(p);byName.set(p.name,rows)}for(const[name,rows]of byName){if(graph.roots[name]){if(!rows.some(p=>p.id===graph.roots[name]))fail('BUNDLE_ROOT_INVALID');continue}if(rows.length!==1)fail('BUNDLE_ROOT_AMBIGUOUS');graph.roots[name]=rows[0].id}const graphBytes=Buffer.from(JSON.stringify(graph,null,2)+'\n');const ids=new Map(graph.packages.map(p=>[p.id,p]));const payload=[];
 for(const f of graph.files){if(!inside(program,resolve(program,f.path))||!f.path.startsWith('store/'))fail('BUNDLE_PATH');const path=join(program,f.path),s=await lstat(path);if(!s.isFile()||s.isSymbolicLink()||await realpath(path)!==path||s.nlink!==1)fail('BUNDLE_FILE_IDENTITY');const b=await readFile(path);if(b.length!==f.size||sha(b)!==f.sha256)fail('BUNDLE_SOURCE_CHANGED');if(kind==='full'||sepOwners.has(ids.get(f.path.split('/')[1])?.name))payload.push(f.path)}
 const pending=[];async function tree(base,at,prefix,ancestors=[]){const canonical=await realpath(at);if(!inside(base,canonical))fail('BUNDLE_RUNTIME_ESCAPE');const s=await stat(canonical);if(s.isDirectory()){if(ancestors.includes(canonical))fail('BUNDLE_RUNTIME_CYCLE');for(const e of await readdir(at))await tree(base,join(at,e),prefix+'/'+e,[...ancestors,canonical])}else if(s.isFile()){if(prefix.split('/').some(x=>/^\.env(?:$|\.)/.test(x)))fail('BUNDLE_PRIVATE_FILE');pending.push({source:canonical,path:prefix,mode:s.mode&0o111?0o755:0o644})}else fail('BUNDLE_FILE_TYPE')}
 await tree(await realpath(runtime),runtime,'runtime');for(const name of ['node','pnpm'])await tree(await realpath(runtime),join(runtime,'primary-runtime/dependencies',name),'runtime/'+name);for(const name of await readdir(join(packaging,'bootstrap'))){if(['start.vbs','start.ps1'].includes(name))continue;pending.push({source:join(packaging,'bootstrap',name),path:'bootstrap/'+name,mode:name==='start.sh'?0o755:0o644})}pending.push({source:join(packaging,'installer.mjs'),path:'installer.mjs',mode:0o644});
 let desktop;if(desktopPayload){const p=JSON.parse(await readFile(join(desktopPayload,'PAYLOAD.json')));desktop={schema:1,platform:p.platform+'-'+p.arch,version:p.version,executable:p.platform==='darwin'?'Electron.app/Contents/MacOS/Electron':'electron',archive:p.archive,files:p.files,links:p.links};await verifyDesktopPayload(join(desktopPayload,'electron'),desktop);for(const name of ['dsh-sep-brand','dsh-sep-plugin-group'])if(!graph.roots[name])fail('BUNDLE_SEP_COMPOSITION');for(const f of desktop.files)pending.push({source:join(desktopPayload,'electron',f.path),path:'runtime/desktop/'+f.path,mode:f.mode,expected:f});}
 await mkdir(destination);const support=[];async function put(path,b,mode=0o644){const p=join(destination,path);await mkdir(dirname(p),{recursive:true});await writeFile(p,b,{flag:'wx'});await chmod(p,mode);return{path,size:b.length,sha256:sha(b),mode}}
 for(const f of graph.files)if(payload.includes(f.path)){const b=await readFile(join(program,f.path));if(b.length!==f.size||sha(b)!==f.sha256)fail('BUNDLE_SOURCE_CHANGED');await put('payload/'+f.path,b,f.mode)}
 for(const f of pending){const b=await readFile(f.source);if(f.expected&&(b.length!==f.expected.size||sha(b)!==f.expected.sha256))fail('BUNDLE_DESKTOP_CHANGED');support.push(await put(f.path,b,f.mode));}
 const raw=await readFile(template,'utf8');let t=JSON.parse(raw.replaceAll('@probe@','@ROOT@').replaceAll('@program-url@','@PROGRAM_URL@').replaceAll('@program@','@ROOT@/program').replaceAll('202bc849-b52e-4147-bda7-7753368c2d8d','@PROJECT_ID@'));t=desktopPayload?nativeProfile(t):t;t.config.p1.enabled=true;
 const templates={suite:t.config,patch:t.patch,program:{'package.json':{name:'sep-native-isolated-validation',private:true,type:'module',dependencies:Object.fromEntries(Object.entries(graph.roots).map(([name,id])=>[name,ids.get(id).version])),dsh:{profile:{bundles:['@deepseek-ai/dsh-base','@deepseek-ai/dsh-web-app']}}},'cordis.yml':[],'desktop.cordis.yml':[],'desktop-release.json':{version:'0.1.7-rc.2'}}};
 support.push(await put('templates.json',Buffer.from(JSON.stringify(templates,null,2))));support.push(await put('README.md',Buffer.from('# Internal native installer validation\n\nThis directory is an isolated test candidate, not a public desktop distribution. Desktop-enabled bundles bind native Electron files and internal relative links in manifest.desktop. Physical interaction and signing acceptance remain pending. It must not replace a Windows daily installation. SEP-only requires the exact supported program files; missing or changed host files reject before installation. No private data or credentials are included.\n')));
 const graphRecord=await put('graph.json',graphBytes);const manifest={schema:2,kind,platform:process.platform+'-'+process.arch,hostVersion:'0.1.7-rc.2',sourceGraphHash:sha(inputGraphBytes),graph:graphRecord,payload,support,bootstrap:{schema:1,files:support.filter(f=>f.path.startsWith('bootstrap/')).map(f=>({...f,path:f.path.slice(10)}))},...(desktop?{desktop}:{}),scope:desktop?'Internal native desktop installer candidate; physical interaction and public signing pending':'Internal native managed-host installer validation; Electron payload and interactive acceptance pending'};await put('manifest.json',Buffer.from(JSON.stringify(manifest,null,2)));return{manifest,graphHash:sha(graphBytes)};
}